#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: str, old: str, new: str) -> bool:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    if new in text:
        return False
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"Expected exactly one patch anchor in {path}, found {count}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")
    return True


def patch_runtime() -> bool:
    path = "app/src/main/java/com/aistudio/mediatool/feature/studio/audio/StudioSessionRuntime.kt"
    old = '''    fun moveSelectedByMillis(milliseconds: Long) {\n        scope.launch {\n            val current = _state.value\n            val clipId = current.selectedClipId ?: return@launch\n            val project = current.project ?: return@launch\n            val deltaFrames = milliseconds * project.timelineSampleRate.toLong() / 1_000L\n            applyEdit("move") { StudioEditEngine.move(it, clipId, deltaFrames) }\n        }\n    }\n\n'''
    new = old + '''    fun moveSelectedToPlayhead() {\n        scope.launch {\n            val current = _state.value\n            val clipId = current.selectedClipId ?: return@launch\n            val project = current.project ?: return@launch\n            val clip = project.tracks\n                .asSequence()\n                .flatMap { it.clips.asSequence() }\n                .firstOrNull { it.id == clipId } ?: return@launch\n            val deltaFrames = current.transportFrame - clip.timelineStartFrame\n            applyEdit("move_to_playhead") { StudioEditEngine.move(it, clipId, deltaFrames) }\n        }\n    }\n\n'''
    return replace_once(path, old, new)


def patch_timeline_semantics() -> bool:
    path = "app/src/main/java/com/aistudio/mediatool/feature/studio/ui/StudioTimeline.kt"
    old = '''            .semantics {\n                contentDescription = "Dòng thời gian âm thanh. Chạm vào sóng âm để chuyển vị trí phát hoặc chọn một đoạn."\n            },\n'''
    new = '''            .semantics {\n                contentDescription =\n                    "Dòng thời gian âm thanh trực quan. Không cần kéo hoặc chạm chính xác. Dùng các nút điều hướng và phần Chỉnh đoạn thu để thao tác bằng trình đọc màn hình."\n            },\n'''
    return replace_once(path, old, new)


def patch_workspace_imports() -> bool:
    path = "app/src/main/java/com/aistudio/mediatool/feature/studio/ui/StudioWorkspaceScreen.kt"
    changed = False
    changed |= replace_once(
        path,
        "import androidx.compose.ui.semantics.contentDescription\n",
        "import androidx.compose.ui.semantics.LiveRegionMode\nimport androidx.compose.ui.semantics.contentDescription\n",
    )
    changed |= replace_once(
        path,
        "import androidx.compose.ui.semantics.heading\n",
        "import androidx.compose.ui.semantics.heading\nimport androidx.compose.ui.semantics.liveRegion\n",
    )
    changed |= replace_once(
        path,
        "import com.aistudio.mediatool.feature.studio.data.StudioRecordingTargetRequests\n",
        "import com.aistudio.mediatool.feature.studio.data.StudioEditEngine\nimport com.aistudio.mediatool.feature.studio.data.StudioRecordingTargetRequests\n",
    )
    changed |= replace_once(
        path,
        "import com.aistudio.mediatool.feature.studio.domain.StudioTakeStatus\n",
        "import com.aistudio.mediatool.feature.studio.domain.StudioTakeStatus\nimport com.aistudio.mediatool.feature.studio.domain.StudioTrack\n",
    )
    return changed


